// === Tab: mySketch ===
let PARTICLE_COUNT = 3500;
let FONT_SIZE = 13;

let pos = new Array(PARTICLE_COUNT);
let vel = new Array(PARTICLE_COUNT);
let life = new Array(PARTICLE_COUNT);

let options = new String[] {
  "scale",
  "spawn",
  "multiplier",
  "mode",
  "motionblur" 
};

let modes = new float[] {
  PI,
  TWO_PI,
  HALF_PI,
  QUARTER_PI,
  TAU
};

let selectedOption = 0;

let spawnMode = 0; // 0 = spawn from left and right sides
                   // 1 = spawn from up, down, left and right sides 
                   // 2 = spawn from anywhere 
let noiseScale = 255;
let mode = 2;
let seed = millis();
let multiplier = 0.8;
let motionblur = true;
let propertiesTimer;

function setup()
{

  createCanvas(1000, 1000);
  //createCanvas(windowWidth, windowHeight, WEBGL);
  background(0);
  //blendMode(BLEND);

  textFont(createFont("Consolas", FONT_SIZE));

  noiseSeed(10);

  for (x = 0; x < PARTICLE_COUNT; x++) {
    pos[x] = GetParticleSpawnPosition(x);
    vel[x] = new PVector(random(-1.0, 1.0), random(-1.0, 1.0));
    life[x] = int(random)(10, 500);
  }

  propertiesTimer = millis() + 3000;

  fill(255);
  noFill();
  noStroke();
}

function draw()
{
  if (motionblur) {
    noStroke();
    fill(0, 20);
    rect(0, 0, width, height);  
  }

  for (x = 0; x < PARTICLE_COUNT; x++) {
    let position = pos[x];

    // let noise direction
    let angle = noise(position.x/(noiseScale * 2.5), position.y/(noiseScale * 2.5))*modes[mode]*(noiseScale * 2.5);//4000//2500//noise(position.x/map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, 500), position.y/map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 500)); //200 //50
    vel[x].x = cos(angle);//cos(angle);
    vel[x].y = sin(angle);//sin(angle);

    // let to velocity and position
    vel[x].mult(multiplier);//0.8);//2);
    pos[x].add(vel[x]); // accessing vel here, bad!

    // Colour
    fill(map(angle, 0, 1, 0, 255), map(vel[x].x, 0, 1, 0, 255), map(vel[x].y, 0, 1, 0, 255),life[x]);

    // Draw
    ellipse(pos[x].x, pos[x].y, 2, 2);

    // let and respawn if out of life
    if (life[x] < 0) {
      pos[x] = GetParticleSpawnPosition(x);
      life[x] = int(random)(450, 900);//random(250, 300); 
    } else {
      life[x]--;
    }

    // let around bounds check
    if (pos[x].x < 0) pos[x].x = 1000;
    if (pos[x].x > 1000) pos[x].x = 0;
    if (pos[x].y < 0) pos[x].y = 1000;
    if (pos[x].y > 1000) pos[x].y = 0;
  }

  if (propertiesTimer > millis()) {
    DrawPropertiesWindows();  
  }

}

function mousePressed()
{
  seed = millis();
  propertiesTimer = millis() + 3000;
  noiseSeed(seed);  

}

function keyPressed()
{
    // let and long but works, suck it DRY.
  switch (keyCode)
  { 
    case DOWN:
      selectedOption++;
      if (selectedOption > options.length) {
        selectedOption = 0;  
      }
      break;
    case UP:
      selectedOption--;
      if (selectedOption < 0) {
        selectedOption = options.length;  
      }
      break;
    case RIGHT:
      if (options[selectedOption] == "scale") {
        noiseScale += 2;
      } else if (options[selectedOption] == "spawn") {
        spawnMode++;
        if (spawnMode > 2) spawnMode = 0;
      } else if (options[selectedOption] == "multiplier") {
        multiplier += 0.1;
      } else if (options[selectedOption] == "mode") {
        if (mode + 1 == 5) { 
          mode = 0;
        } else {
          mode++;
        }
      } else if (options[selectedOption] == "motionblur") {
        motionblur = !motionblur;  
      }
      break;
    case LEFT:
      if (options[selectedOption] == "scale") {
        noiseScale -= 2;
      } else if (options[selectedOption] == "spawn") {
        spawnMode--;
        if (spawnMode < 0) spawnMode = 2;
      } else if (options[selectedOption] == "multiplier") {
        multiplier -= 0.1;
      } else if (options[selectedOption] == "mode") {
        if (mode - 1 == 0) {
          mode = modes.length - 1;  
        } else {
          mode--;  
        }
      } else if (options[selectedOption] == "motionblur") {
        motionblur = !motionblur;  
      }
      break;
  } 


  propertiesTimer = millis() + 3000;
}

function DrawPropertiesWindows()
{
  let x = 20;
  let y = 20;

  //fill(0);
  //rect(0, 0, 300, 150);
  fill(255);
  text("Noise Generator", x, y); y += FONT_SIZE;
  text("----------------", x, y); y += FONT_SIZE;
  text("particle count = " + PARTICLE_COUNT, x, y); y += FONT_SIZE;
  text("seed = " + seed, x, y); y += FONT_SIZE; 

  for (i = 0; i < options.length; i++) {

    if (i == selectedOption) {
      fill(255, 0, 0);
    } else {
      fill(255);  
    }
    switch(options[i]) 
    {
      case "scale":
        text("scale = " + noiseScale, x, y); y += FONT_SIZE;
        break;
      case "spawn":
        text("spawn type = " + spawnMode, x, y); y += FONT_SIZE;
        break;
      case "multiplier":
        text("multiplier = " + multiplier, x, y); y+= FONT_SIZE;
        break;
      case "mode":
        let type = "";
        switch(mode) {
          case 0: 
            type = "PI";
            break;
          case 1: 
            type = "TWO_PI";
            break;
          case 2: 
            type = "HALF_PI";
            break;
          case 3:
            type = "QUARTER_PI";
            break;
          case 4:
            type = "TAU";
            break;
        }
        text("mode = " + type, x, y); y += FONT_SIZE;
        break;
      case "motionblur":
        text("motionblur = " + (motionblur ? "ON" : "OFF"), x, y); y += FONT_SIZE;
        break;
    }
  }


  fill(255); 
  text(nfs(frameRate, 1, 2) + " fps", x, y); y += FONT_SIZE; 

  y += FONT_SIZE; text("Use UP and DOWN arrows to navigate", x, y); y += FONT_SIZE;
  text("LEFT and RIGHT arrows decrease and increase selected value", x, y); y += FONT_SIZE;
  text("CLICK mouse to change seed", x, y); y += FONT_SIZE;
}

function GetParticleSpawnPosition(particleIndex)
{
  var pos = new PVector(random(0, width), 0);
  switch (spawnMode)
  {
    case 0:
    {
      pos = new PVector(random(0, width), 0);
      break;
    }
    case 1:
    {
      if (particleIndex % 2 == 0) {
        pos = new PVector(random(width), 0);
      } else {  
        pos = new PVector(0, random(height)); 
      }
      break;
    }
    case 2:
    {
      pos = new PVector(random(0, width), random(0, height)); 
      break;
    }
    default:
    {
      pos = new PVector(random(0, width), 0);
      break;
    }

  }
  return pos;
}

